import{_ as o,o as r,c as a,j as e}from"./chunks/framework.44aEvdQQ.js";const f=JSON.parse(`{"title":"Reframing Ownership - The Wealth Generator","description":"","frontmatter":{"title":"Reframing Ownership - The Wealth Generator","order":4,"subtitle":"Business as asset that shouldn't require you to do the work"},"headers":[],"relativePath":"about/chapters/04-reframing-ownership-the-wealth-generator.md","filePath":"about/chapters/04-reframing-ownership-the-wealth-generator.md"}`),n={name:"about/chapters/04-reframing-ownership-the-wealth-generator.md"};function s(i,t,h,l,u,c){return r(),a("div",null,[...t[0]||(t[0]=[e("p",null,[e("em",null,"Business as asset that shouldn't require you to do the work")],-1),e("p",null,`If you're reading this it's because you're looking for ways to improve the health of your small business. You have the power to change its course but you're concerned about heading in the right direction. Unlike the owners of large businesses, you have to look your staff in the eyes when they ask for a salary increase. You feel the walls closing in — sensing prospects demand ever-decreasing prices for your work, hearing your staff complain about the rising cost of living. To normalize making profit is to close the lid on many of the concerns that you cannot control. No healthy business ignores the need to sell their offering for more than they pay to produce it. The mental model shift: from "I am the business" to "I own a wealth-generating machine." Success can and should look like: you don't do the do, you're the owner who takes risks at certain intervals. This is a new thought for most ICP owners—they've never considered it because they're on the treadmill. Midterm and long-term thinking as luxury they can't afford (but must).`,-1)])])}const m=o(n,[["render",s]]);export{f as __pageData,m as default};
